-- PCM · Preventivas de válvulas diafragma (prontuário de troca de diafragmas).
--
-- Leva para o site a folha impressa "Prontuário troca de diafragmas REV 12":
--   pcm.ativo              equipamento (FTD01, PGD15, BLD02...) — tabela prevista na 01-base
--   pcm.checklist_item     válvulas do prontuário de cada equipamento (TAG, DN, código, marca, trocar/avaliar)
--   pcm.preventiva         uma folha lançada pelo PCM para um equipamento, com OM e data
--   pcm.preventiva_item    a linha da folha: trocado S/N, vida 1–4 e o técnico que preencheu
--   pcm.preventiva_observacao  "Observações técnicos", uma por pessoa, com autor
--
-- Quem faz o quê (a API confere; a policy é a segunda barreira):
--   admin, gestor e pcm cadastram equipamentos, lançam, corrigem e cancelam folhas;
--   lider e tecnico leem e preenchem folhas em aberto e registram observações.
-- O item da folha guarda uma cópia da válvula no momento do lançamento: mudar o
-- prontuário depois não reescreve o histórico já preenchido.
--
-- 02a deixou o schema pcm sem privilégio padrão de propósito: toda tabela nova entra
-- aqui com GRANT e policy escritos na mesma migration. 02g aplica, a cada deploy, a
-- leitura provisória (pcm/gestor/admin) e o CRUD do admin em todas as tabelas de pcm;
-- as policies abaixo somam a elas (policies permissivas combinam por OU).
BEGIN;

CREATE TABLE IF NOT EXISTS pcm.checklist_item (
  id               uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  ativo_id         uuid        NOT NULL REFERENCES pcm.ativo(id) ON DELETE CASCADE,
  posicao          smallint    NOT NULL DEFAULT 0,
  local_tanque     text        NOT NULL DEFAULT '',
  tag              text        NOT NULL,
  descricao        text        NOT NULL DEFAULT '',
  medida           text        NOT NULL DEFAULT '',
  dn               text        NOT NULL DEFAULT '',
  codigo_material  text        NOT NULL DEFAULT '',
  marca            text        NOT NULL DEFAULT '',
  acao             text        NOT NULL DEFAULT 'avaliar' CHECK (acao IN ('trocar', 'avaliar')),
  ativo            boolean     NOT NULL DEFAULT true,
  criado_em        timestamptz NOT NULL DEFAULT now(),
  atualizado_em    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_checklist_item_ativo ON pcm.checklist_item (ativo_id, ativo, posicao);

CREATE TABLE IF NOT EXISTS pcm.preventiva (
  id                  uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  ativo_id            uuid        NOT NULL REFERENCES pcm.ativo(id),
  numero_om           text        NOT NULL DEFAULT '',
  data_prevista       date        NOT NULL DEFAULT current_date,
  status              text        NOT NULL DEFAULT 'aberta'
                                  CHECK (status IN ('aberta', 'em_execucao', 'concluida', 'cancelada')),
  observacoes_pcm     text        NOT NULL DEFAULT '',
  origem              text        NOT NULL DEFAULT 'site' CHECK (origem IN ('site', 'planilha')),
  lancada_por         uuid        REFERENCES core.usuario(id) ON DELETE SET NULL,
  lancada_por_nome    text        NOT NULL DEFAULT '',
  lancada_em          timestamptz NOT NULL DEFAULT now(),
  concluida_por       uuid        REFERENCES core.usuario(id) ON DELETE SET NULL,
  concluida_por_nome  text        NOT NULL DEFAULT '',
  concluida_em        timestamptz,
  atualizado_em       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ck_preventiva_conclusao CHECK (status <> 'concluida' OR concluida_em IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS ix_preventiva_ativo  ON pcm.preventiva (ativo_id, data_prevista DESC);
CREATE INDEX IF NOT EXISTS ix_preventiva_status ON pcm.preventiva (status, data_prevista);

CREATE TABLE IF NOT EXISTS pcm.preventiva_item (
  id                 uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  preventiva_id      uuid        NOT NULL REFERENCES pcm.preventiva(id) ON DELETE CASCADE,
  checklist_item_id  uuid        REFERENCES pcm.checklist_item(id) ON DELETE SET NULL,
  posicao            smallint    NOT NULL DEFAULT 0,
  local_tanque       text        NOT NULL DEFAULT '',
  tag                text        NOT NULL DEFAULT '',
  descricao          text        NOT NULL DEFAULT '',
  medida             text        NOT NULL DEFAULT '',
  dn                 text        NOT NULL DEFAULT '',
  codigo_material    text        NOT NULL DEFAULT '',
  marca              text        NOT NULL DEFAULT '',
  acao               text        NOT NULL DEFAULT 'avaliar' CHECK (acao IN ('trocar', 'avaliar')),
  trocado            boolean,
  vida               smallint    CHECK (vida IS NULL OR vida BETWEEN 1 AND 4),
  data_execucao      date,
  observacao         text        NOT NULL DEFAULT '',
  tecnico_id         uuid        REFERENCES core.usuario(id) ON DELETE SET NULL,
  tecnico_nome       text        NOT NULL DEFAULT '',
  preenchido_em      timestamptz
);
CREATE INDEX IF NOT EXISTS ix_preventiva_item_prev      ON pcm.preventiva_item (preventiva_id, posicao);
CREATE INDEX IF NOT EXISTS ix_preventiva_item_checklist ON pcm.preventiva_item (checklist_item_id);

CREATE TABLE IF NOT EXISTS pcm.preventiva_observacao (
  id             uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  preventiva_id  uuid        NOT NULL REFERENCES pcm.preventiva(id) ON DELETE CASCADE,
  texto          text        NOT NULL CHECK (length(texto) BETWEEN 1 AND 2000),
  autor_id       uuid        REFERENCES core.usuario(id) ON DELETE SET NULL,
  autor_nome     text        NOT NULL DEFAULT '',
  criado_em      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_preventiva_obs_prev ON pcm.preventiva_observacao (preventiva_id, criado_em);

COMMENT ON TABLE pcm.checklist_item IS 'Válvulas diafragma do prontuário de cada equipamento. Desativar (ativo=false) tira da próxima folha sem apagar o histórico.';
COMMENT ON TABLE pcm.preventiva IS 'Folha de preventiva de diafragmas lançada pelo PCM para um equipamento. Técnico e líder preenchem enquanto está aberta ou em execução.';
COMMENT ON TABLE pcm.preventiva_item IS 'Linha da folha: cópia da válvula no lançamento + trocado S/N, vida 1–4 (1=0%, 2=25%, 3=50%, 4=90%) e o técnico que preencheu (gravado pelo servidor a partir da sessão).';
COMMENT ON TABLE pcm.preventiva_observacao IS 'Observações dos técnicos na folha, com autor gravado pelo servidor.';

-- ------------------------------------------------------------------ quem alcança
CREATE OR REPLACE FUNCTION app.pcm_equipe() RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT app.usuario_ativo() AND app.tem_perfil(ARRAY['admin','gestor','pcm','lider','tecnico'])
$$;
CREATE OR REPLACE FUNCTION app.pcm_gestao() RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT app.usuario_ativo() AND app.tem_perfil(ARRAY['admin','gestor','pcm'])
$$;
-- SECURITY DEFINER só para ler o status da folha dentro da policy do item sem
-- depender da policy de leitura da folha; devolve apenas verdadeiro/falso.
CREATE OR REPLACE FUNCTION app.pcm_preventiva_aberta(p_preventiva uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pcm, pg_temp AS $$
  SELECT EXISTS (SELECT 1 FROM pcm.preventiva WHERE id = p_preventiva AND status IN ('aberta','em_execucao'))
$$;
COMMENT ON FUNCTION app.pcm_equipe() IS 'Quem lê e preenche folhas de preventiva: admin, gestor, pcm, líder e técnico.';
COMMENT ON FUNCTION app.pcm_gestao() IS 'Quem cadastra equipamentos e lança, corrige ou cancela folhas de preventiva: admin, gestor e pcm.';
REVOKE ALL ON FUNCTION app.pcm_equipe(), app.pcm_gestao(), app.pcm_preventiva_aberta(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.pcm_equipe(), app.pcm_gestao(), app.pcm_preventiva_aberta(uuid) TO biotrop_app, biotrop_ro;

GRANT SELECT, INSERT, UPDATE, DELETE ON pcm.ativo, pcm.checklist_item, pcm.preventiva,
  pcm.preventiva_item, pcm.preventiva_observacao TO biotrop_app;
GRANT SELECT ON pcm.ativo, pcm.checklist_item, pcm.preventiva,
  pcm.preventiva_item, pcm.preventiva_observacao TO biotrop_ro;

ALTER TABLE pcm.ativo                 ENABLE ROW LEVEL SECURITY;
ALTER TABLE pcm.checklist_item        ENABLE ROW LEVEL SECURITY;
ALTER TABLE pcm.preventiva            ENABLE ROW LEVEL SECURITY;
ALTER TABLE pcm.preventiva_item       ENABLE ROW LEVEL SECURITY;
ALTER TABLE pcm.preventiva_observacao ENABLE ROW LEVEL SECURITY;

-- Equipamentos e prontuário: a equipe lê, a gestão mantém.
DROP POLICY IF EXISTS ativo_equipe_sel ON pcm.ativo;
CREATE POLICY ativo_equipe_sel ON pcm.ativo FOR SELECT TO biotrop_app, biotrop_ro USING (app.pcm_equipe());
DROP POLICY IF EXISTS ativo_gestao ON pcm.ativo;
CREATE POLICY ativo_gestao ON pcm.ativo FOR ALL TO biotrop_app USING (app.pcm_gestao()) WITH CHECK (app.pcm_gestao());

DROP POLICY IF EXISTS checklist_item_equipe_sel ON pcm.checklist_item;
CREATE POLICY checklist_item_equipe_sel ON pcm.checklist_item FOR SELECT TO biotrop_app, biotrop_ro USING (app.pcm_equipe());
DROP POLICY IF EXISTS checklist_item_gestao ON pcm.checklist_item;
CREATE POLICY checklist_item_gestao ON pcm.checklist_item FOR ALL TO biotrop_app USING (app.pcm_gestao()) WITH CHECK (app.pcm_gestao());

-- Folha: a equipe lê todas e altera só a que está em aberto (e pode concluí-la).
DROP POLICY IF EXISTS preventiva_equipe_sel ON pcm.preventiva;
CREATE POLICY preventiva_equipe_sel ON pcm.preventiva FOR SELECT TO biotrop_app, biotrop_ro USING (app.pcm_equipe());
DROP POLICY IF EXISTS preventiva_gestao ON pcm.preventiva;
CREATE POLICY preventiva_gestao ON pcm.preventiva FOR ALL TO biotrop_app USING (app.pcm_gestao()) WITH CHECK (app.pcm_gestao());
DROP POLICY IF EXISTS preventiva_equipe_upd ON pcm.preventiva;
CREATE POLICY preventiva_equipe_upd ON pcm.preventiva FOR UPDATE TO biotrop_app
  USING (app.pcm_equipe() AND status IN ('aberta','em_execucao'))
  WITH CHECK (app.pcm_equipe() AND status IN ('aberta','em_execucao','concluida'));

DROP POLICY IF EXISTS preventiva_item_equipe_sel ON pcm.preventiva_item;
CREATE POLICY preventiva_item_equipe_sel ON pcm.preventiva_item FOR SELECT TO biotrop_app, biotrop_ro USING (app.pcm_equipe());
DROP POLICY IF EXISTS preventiva_item_gestao ON pcm.preventiva_item;
CREATE POLICY preventiva_item_gestao ON pcm.preventiva_item FOR ALL TO biotrop_app USING (app.pcm_gestao()) WITH CHECK (app.pcm_gestao());
DROP POLICY IF EXISTS preventiva_item_equipe_upd ON pcm.preventiva_item;
CREATE POLICY preventiva_item_equipe_upd ON pcm.preventiva_item FOR UPDATE TO biotrop_app
  USING (app.pcm_equipe() AND app.pcm_preventiva_aberta(preventiva_id))
  WITH CHECK (app.pcm_equipe() AND app.pcm_preventiva_aberta(preventiva_id));

DROP POLICY IF EXISTS preventiva_obs_equipe_sel ON pcm.preventiva_observacao;
CREATE POLICY preventiva_obs_equipe_sel ON pcm.preventiva_observacao FOR SELECT TO biotrop_app, biotrop_ro USING (app.pcm_equipe());
DROP POLICY IF EXISTS preventiva_obs_gestao ON pcm.preventiva_observacao;
CREATE POLICY preventiva_obs_gestao ON pcm.preventiva_observacao FOR ALL TO biotrop_app USING (app.pcm_gestao()) WITH CHECK (app.pcm_gestao());
DROP POLICY IF EXISTS preventiva_obs_equipe_ins ON pcm.preventiva_observacao;
CREATE POLICY preventiva_obs_equipe_ins ON pcm.preventiva_observacao FOR INSERT TO biotrop_app
  WITH CHECK (app.pcm_equipe() AND autor_id = app.usuario_atual() AND app.pcm_preventiva_aberta(preventiva_id));

-- ------------------------------------------------------------------ carga do prontuário REV 12
-- Roda só para equipamento que ainda não existe: um equipamento editado ou
-- desativado pelo PCM nunca é recriado nem sobrescrito por um deploy.
-- Formato: {c:código, n:nome, m:CAMM, l:grupo, om, d:data, i:[[local,tag,descrição,
-- medida,DN,código,marca,ação, data,trocado,vida,técnico], ...]}. As abas com a folha
-- já preenchida no papel entram como preventiva concluída de origem "planilha".
DO $carga$
DECLARE
  e jsonb; it jsonb; v_ativo uuid; v_prev uuid; v_item uuid; pos int; hist boolean;
  v_data date; v_fim date; v_tecnicos text;
BEGIN
  FOR e IN SELECT value FROM jsonb_array_elements(
