{"c":"BLD04","n":"Blender 4","m":"CAMM 2","l":"Blenders","om":"","d":"","i":[]},
{"c":"BLD05","n":"Blender 5","m":"CAMM 2","l":"Blenders","om":"","d":"","i":[]}
]$seed$::jsonb) LOOP
    v_ativo := NULL;
    INSERT INTO pcm.ativo (codigo, nome, camm, local)
    VALUES (e->>'c', e->>'n', NULLIF(e->>'m','')::core.camm, e->>'l')
    ON CONFLICT (codigo) DO NOTHING
    RETURNING id INTO v_ativo;
    CONTINUE WHEN v_ativo IS NULL;

    hist := EXISTS (SELECT 1 FROM jsonb_array_elements(e->'i') x
                     WHERE x->>9 IS NOT NULL OR x->>10 IS NOT NULL OR x->>8 IS NOT NULL);
    v_prev := NULL;
    IF hist THEN
      SELECT min((x->>8)::date), max((x->>8)::date),
             string_agg(DISTINCT NULLIF(x->>11,''), ', ')
        INTO v_data, v_fim, v_tecnicos
        FROM jsonb_array_elements(e->'i') x;
      INSERT INTO pcm.preventiva (ativo_id, numero_om, data_prevista, status, origem,
             lancada_por_nome, lancada_em, concluida_por_nome, concluida_em, observacoes_pcm)
      VALUES (v_ativo, coalesce(e->>'om',''), coalesce(NULLIF(e->>'d','')::date, v_data, current_date),
             'concluida', 'planilha', 'Importado do prontuário REV 12',
             coalesce(NULLIF(e->>'d','')::date, v_data, current_date)::timestamptz,
             coalesce(v_tecnicos,''), coalesce(v_fim, v_data, current_date)::timestamptz,
             'Folha preenchida em papel e importada do prontuário REV 12.')
      RETURNING id INTO v_prev;
    END IF;

    pos := 0;
    FOR it IN SELECT value FROM jsonb_array_elements(e->'i') LOOP
      pos := pos + 1;
      INSERT INTO pcm.checklist_item (ativo_id, posicao, local_tanque, tag, descricao, medida,
             dn, codigo_material, marca, acao)
      VALUES (v_ativo, pos, it->>0, it->>1, it->>2, it->>3, it->>4, it->>5, it->>6, it->>7)
      RETURNING id INTO v_item;
      IF v_prev IS NOT NULL THEN
        INSERT INTO pcm.preventiva_item (preventiva_id, checklist_item_id, posicao, local_tanque,
               tag, descricao, medida, dn, codigo_material, marca, acao, trocado, vida,
               data_execucao, tecnico_nome, preenchido_em)
        VALUES (v_prev, v_item, pos, it->>0, it->>1, it->>2, it->>3, it->>4, it->>5, it->>6, it->>7,
               (it->>9)::boolean, (it->>10)::smallint, (it->>8)::date, coalesce(it->>11,''),
               CASE WHEN it->>8 IS NOT NULL THEN (it->>8)::date::timestamptz END);
      END IF;
    END LOOP;
  END LOOP;
END
$carga$;

COMMIT;
